import sys
from collections import deque, defaultdict

n, k = map(int, sys.stdin.readline().split())
a = 0
b = 0
for _ in range(n):
    val = int(sys.stdin.readline())
    if val == 50:
        a += 1
    else:
        b += 1

MOD = 1000000007
choose = [[0] * 100 for _ in range(100)]
for i in range(100):
    choose[i][0] = 1
for i in range(1, 100):
    for j in range(1, i + 1):
        choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

def fill_choose():
    for i in range(100):
        choose[i][0] = 1
    for i in range(1, 100):
        for j in range(1, i + 1):
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

q = deque()
ways = dict()

start_mask = 1000000 + 100 * a + b
q.append(start_mask)
ways[start_mask] = (0, 1)

def bfs(mask):
    boat = mask // 1000000
    nA = (mask % 1000000) // 100
    nB = mask % 100
    if boat > 0:
        for i in range(nA, -1, -1):
            if 50 * (nA - i) > k:
                continue
            for j in range(nB, -1, -1):
                if 50 * (nA - i) + 100 * (nB - j) > k:
                    continue
                if i != nA or j != nB:
                    resolve(i, j, boat, mask, choose[nA][i] * choose[nB][j] % MOD)
    else:
        for i in range(nA, a + 1):
            if 50 * (i - nA) > k:
                continue
            for j in range(nB, b + 1):
                if 50 * (i - nA) + 100 * (j - nB) > k:
                    continue
                if i != nA or j != nB:
                    resolve(i, j, boat, mask, choose[a - nA][i - nA] * choose[b - nB][j - nB] % MOD)

def resolve(i, j, boat, mask, edgeWays):
    newMask = 1000000 * (1 - boat) + i * 100 + j
    d, w = ways.get(mask, (0, 0))
    newD, newW = ways.get(newMask, (d + 1, 0))
    if newMask not in ways:
        ways[newMask] = (d + 1, 0)
        q.append(newMask)
    if ways[newMask][0] == d + 1:
        ways[newMask] = (ways[newMask][0], (ways[newMask][1] + w * edgeWays) % MOD)

while q:
    current_mask = q.popleft()
    bfs(current_mask)

if 0 in ways:
    print(str(ways[0][0]) + "\n" + str(ways[0][1]))
else:
    print("-1\n0")

